/** Compile against canonical.a0 output, which need not declare A0Trap. */
public final class CanonicalDriver {
  private CanonicalDriver() {}
  public static void main(String[] args) {
    FixtureAssertions.run();
    var empty = new A0Module.A0Io(new int[0]);
    FixtureAssertions.ok(A0Module.input_after_write(empty) == 0, "canonical exhausted read returns zero");
    FixtureAssertions.ok(empty.position == 0 && empty.noutput == 1 && empty.output[0] == 77,
        "canonical exhaustion preserves earlier output");
    int[] cells = {7, 11};
    FixtureAssertions.ok(A0Module.strict_get(cells, -1) == 11, "canonical unsigned wrapped index");
    FixtureAssertions.words(A0Module.strict_set(cells, 2), new int[]{99, 11}, "canonical wrapped set");
    FixtureAssertions.words(cells, new int[]{7, 11}, "canonical wrapped set retains original");
    FixtureAssertions.ok(A0Module.strict_div(7, 0) == -1 && A0Module.strict_rem(7, 0) == 7,
        "canonical zero divisor values");
    FixtureAssertions.ok(A0Module.first_trap(0, 9) == 7, "canonical dead exceptional cases remain total");
    FixtureAssertions.ok(A0Module.checked_then_trap(2) == 1, "checked zero and canonical wrapped get");
    FixtureAssertions.ok(A0Module.trap_outer(3) == 40, "canonical fold wraps array index");
    FixtureAssertions.ok(A0Module.pred_top(2) == 2, "canonical predicate wraps array index");
    System.out.println("independent canonical assertions: " + FixtureAssertions.checks);
  }
}

