import java.util.Arrays;

/** Fixed-value checks shared by canonical and strict modules. No compiler/interpreter oracle. */
final class FixtureAssertions {
  private FixtureAssertions() {}
  static int checks;
  static void ok(boolean value, String label) {
    checks++;
    if (!value) throw new AssertionError(label);
  }
  static void words(int[] actual, int[] expected, String label) {
    ok(Arrays.equals(actual, expected), label);
  }
  static void checked(A0Module.R_r2_u_b actual, int value, boolean valid, String label) {
    ok(actual.f0() == value && actual.f1() == valid, label);
  }
  static void run() {
    int[] leaf = {7, 11};
    int[][] rows = {leaf, leaf};
    var snap = A0Module.nested_snapshot(rows, 1);
    ok(snap.f0() == rows && snap.f1() != rows, "outer snapshot identity");
    ok(snap.f2() == leaf && snap.f3() == leaf, "retained child views");
    ok(rows[0] == leaf && rows[1] == leaf, "original outer aliases");
    words(leaf, new int[]{7, 11}, "original nested input unchanged");
    ok(snap.f1()[0] == leaf && snap.f1()[1] != leaf, "only changed path cloned");
    words(snap.f1()[1], new int[]{7, 99}, "fresh nested value");

    var record = new A0Module.R_r2_a2_u_a2_u(leaf, leaf);
    var recsnap = A0Module.record_snapshot(record);
    ok(recsnap.f0() == record && recsnap.f1() != record, "record snapshot identity");
    ok(recsnap.f2() == leaf && recsnap.f1().f1() == leaf, "record sibling aliases");
    ok(recsnap.f1().f0() != leaf, "changed record field cloned");
    words(recsnap.f1().f0(), new int[]{99, 11}, "fresh record field value");
    words(leaf, new int[]{7, 11}, "record update leaves original child");

    int[] original = {10, 20};
    var zero = A0Module.alias_fold(original, 0);
    ok(zero.f0() == zero.f1(), "zero-trip fold returns exact initial record");
    ok(zero.f0().f0() == original && zero.f2() == original, "zero-trip extra alias");
    ok(zero.f1().f1() == 0, "zero-trip counter");
    var four = A0Module.alias_fold(original, 4);
    ok(four.f0().f0() == original && four.f2() == original, "fold retained input alias");
    ok(four.f0().f1() == 0 && four.f1().f1() == 4, "fold old and final counters");
    words(four.f1().f0(), new int[]{12, 23}, "fold reads immutable extra each trip");
    words(original, new int[]{10, 20}, "fold input remains unchanged");
    ok(four.f1().f0() != original, "fold changed state clone");
    for (int count : new int[]{0, 1, Integer.MIN_VALUE, -1}) {
      var loop = A0Module.alias_loop(original, count);
      int expectedTrips = count == 0 ? 0 : 1;
      ok(loop.f1().f1() == expectedTrips, "unsigned loop count and early predicate");
      words(loop.f1().f0(), new int[]{10, 20}, "one-trip loop state value");
      ok(loop.f2() == original, "loop retains extra alias");
      ok((loop.f1().f0() == original) == (count == 0), "loop state copy identity");
    }
    words(original, new int[]{10, 20}, "loop input remains unchanged");

    checked(A0Module.flag_add(-1, 1), 0, false, "cadd wrap flag");
    checked(A0Module.flag_add(0x7fffffff, 1), Integer.MIN_VALUE, true, "cadd signed seam");
    checked(A0Module.flag_sub(0, 1), -1, false, "csub borrow");
    checked(A0Module.flag_sub(-1, -1), 0, true, "csub equal high values");
    checked(A0Module.flag_mul(-1, -1), 1, false, "cmul full high product");
    checked(A0Module.flag_mul(65536, 65536), 0, false, "cmul exact 2^32");
    checked(A0Module.flag_mul(65535, 65537), -1, true, "cmul exact UINT32_MAX");
    checked(A0Module.flag_mul(0, -1), 0, true, "cmul zero high operand");
    checked(A0Module.flag_div(-1, 2), 2147483647, true, "cdiv unsigned");
    checked(A0Module.flag_div(17, 0), 0, false, "cdiv total zero");
    checked(A0Module.flag_rem(-1, 0), 0, false, "crem total zero");
    checked(A0Module.flag_rem(-1, 2), 1, true, "crem unsigned");
    int[] cells = {5, 6, -1};
    checked(A0Module.flag_get(cells, -1), 0, false, "cget unsigned out of range");
    checked(A0Module.flag_get(cells, 3), 0, false, "cget exact bound");
    checked(A0Module.flag_get(cells, 2), -1, true, "cget last value");

    int[] input = {-1, 7};
    var io = new A0Module.A0Io(input);
    var other = new A0Module.A0Io(new int[]{123});
    input[0] = 456;
    ok(io.input.length == 256 && io.output.length == 1024 && io.ninput == 2,
        "default IO layout");
    var first = A0Module.io_pair(io);
    ok(first.f0() == -1 && first.f1() == io, "read tuple value then exact IO");
    ok(io.position == 1 && io.noutput == 1 && io.output[0] == -1, "input copy and first IO effect");
    ok(other.position == 0 && other.noutput == 0 && other.input[0] == 123, "fresh IO isolation");
    var second = A0Module.io_pair(io);
    ok(second.f0() == 7 && second.f1() == io && io.position == 2,
        "second IO token and input order");
    ok(io.noutput == 2 && io.output[1] == 7, "second IO output order");

    var saturated = new A0Module.A0Io(new int[0]);
    saturated.noutput = 1023;
    saturated.output[0] = 55;
    ok(A0Module.puts_probe(saturated) == saturated, "puts exact IO identity");
    ok(saturated.noutput == 1024 && saturated.output[1023] == 3,
        "puts retains only length when one slot remains");
    ok(saturated.output[0] == 55 && saturated.position == 0, "puts preserves earlier output and input");

    var helperIo = new A0Module.A0Io(new int[]{9});
    var helperRead = A0Module.read(helperIo);
    ok(helperRead.f0() == 9 && helperRead.f1() == helperIo, "export named read");
    ok(A0Module.write(helperIo, 8) == helperIo, "export named write");
    ok(A0Module.puts(helperIo, new int[]{1, 2, 3}) == helperIo, "export named puts");
    ok(helperIo.noutput == 5, "named helper exports emit expected count");
    words(Arrays.copyOf(helperIo.output, 5), new int[]{8, 3, 1, 2, 3}, "named helper exports output");
    int[] beforeSet = {1, 2};
    int[] afterSet = A0Module.set_a2_u(beforeSet, 1, 88);
    words(beforeSet, new int[]{1, 2}, "export named set helper preserves input");
    words(afterSet, new int[]{1, 88}, "export named set helper value");
    var pair = new A0Module.R_r2_u_u(3, 4);
    var pairNext = A0Module.put_r2_u_u_0(pair, 22);
    ok(pair.f0() == 3 && pairNext.f0() == 22 && pairNext.f1() == 4,
        "export named put helper");
    ok(A0Module.a0_cadd(-1, 2) == 1, "export named checked helper");

    ok(A0Module.yield(false, 0) && !A0Module.yield(true, 0), "direct qualified yield call");
    ok(A0Module.yield_call(false) && !A0Module.yield_call(true), "generated yield call");
    ok(!A0Module.yield_fold(0) && !A0Module.yield_fold(2) && A0Module.yield_fold(3),
        "generated yield fold body");
    ok(!A0Module.yield_loop(0) && A0Module.yield_loop(3), "generated yield loop predicate and body");
    ok(A0Module.record() == 101 && A0Module.var() == 102 && A0Module.sealed() == 103
        && A0Module.permits() == 104, "valid contextual method names");
    ok(A0Module.getclass() == 105 && A0Module.tostring() == 106, "case-sensitive Object names");

    int[] predicateCounts = {0, 1, 4};
    int[] predicateStates = {0, 1, 2};
    int[][] predicateTags = {new int[0], new int[]{10, 20}, new int[]{10, 20, 10, 20, 10}};
    for (int caseIndex = 0; caseIndex < predicateCounts.length; caseIndex++) {
      var predicateIo = new A0Module.A0Io(new int[]{999});
      int predicateResult = A0Module.predicate_io(predicateCounts[caseIndex], predicateIo);
      ok(predicateResult == predicateStates[caseIndex], "predicate IO final scalar state");
      ok(predicateIo.position == 0 && predicateIo.ninput == 1 && predicateIo.input[0] == 999,
          "predicate and body preserve unread input");
      ok(predicateIo.noutput == predicateTags[caseIndex].length,
          "final false predicate writes its tag without executing the body");
      words(Arrays.copyOf(predicateIo.output, predicateIo.noutput), predicateTags[caseIndex],
          "predicate IO tags occur before their body and include final false predicate");
    }
  }
}

