import java.util.Arrays;
import java.util.Objects;

/** Compile against strict.a0 output; this is a direct trap/public-ABI driver. */
public final class Driver {
  private Driver() {}
  @FunctionalInterface interface Action { void run(); }
  static final String BOUNDS_FIX = "keep the index below the length (check it, or use cget for a total read)";
  static final String DIV_FIX = "test the divisor first, or use cdiv/crem, which return (0,false) for a zero divisor";
  static final String INPUT_FIX = "supply more input words, or stop reading when the input is exhausted";
  static void trap(Action action, String id, String kind, String fn, String at, String trip,
                   String[] chain, String fix, String message) {
    boolean caught = false;
    try { action.run(); }
    catch (A0Module.A0Trap t) {
      caught = true;
      FixtureAssertions.ok(t.id.equals(id) && t.kind.equals(kind) && t.fn.equals(fn), "trap id/kind/fn");
      FixtureAssertions.ok(Objects.equals(t.at, at) && Objects.equals(t.trip, trip), "trap at/trip");
      FixtureAssertions.ok(Arrays.equals(t.chain, chain), "trap copied call chain");
      FixtureAssertions.ok(t.fix.equals(fix) && t.getMessage().equals(message), "trap fix/message");
      String expected = "runtime: trap " + kind + " fn=" + fn + " at=" + (at == null ? "-" : at)
          + " trip=" + (trip == null ? "-" : trip) + " chain=" + String.join(">", chain) + " fix: " + fix;
      FixtureAssertions.ok(t.line().equals(expected), "exact trap diagnostic line");
    }
    FixtureAssertions.ok(caught, "expected A0Trap");
  }
  static void direct(Action action, String id, String kind, String fn, String fix, String message) {
    trap(action, id, kind, fn, null, null, new String[]{fn}, fix, message);
  }
  public static void main(String[] args) {
    FixtureAssertions.run();
    int[] cells = {7, 11};
    FixtureAssertions.ok(A0Module.strict_get(cells, 1) == 11, "safe strict get");
    direct(() -> { A0Module.strict_get(cells, 2); }, "A0710", "bounds", "strict_get", BOUNDS_FIX,
        "strict_get: index out of bounds (strict profile)");
    direct(() -> { A0Module.strict_get(cells, -1); }, "A0710", "bounds", "strict_get", BOUNDS_FIX,
        "strict_get: index out of bounds (strict profile)");
    direct(() -> { A0Module.strict_set(cells, 2); }, "A0710", "bounds", "strict_set", BOUNDS_FIX,
        "strict_set: index out of bounds (strict profile)");
    FixtureAssertions.words(cells, new int[]{7, 11}, "failed set preserves passed array");
    FixtureAssertions.ok(A0Module.strict_div(-1, 2) == 2147483647 && A0Module.strict_rem(-1, 2) == 1,
        "safe strict unsigned div/rem");
    direct(() -> { A0Module.strict_div(7, 0); }, "A0711", "divzero", "strict_div", DIV_FIX,
        "strict_div: division by zero (strict profile)");
    direct(() -> { A0Module.strict_rem(7, 0); }, "A0711", "divzero", "strict_rem", DIV_FIX,
        "strict_rem: division by zero (strict profile)");
    direct(() -> { A0Module.first_trap(0, 9); }, "A0711", "divzero", "first_trap", DIV_FIX,
        "first_trap: division by zero (strict profile)");
    direct(() -> { A0Module.first_trap(1, 9); }, "A0710", "bounds", "first_trap", BOUNDS_FIX,
        "first_trap: index out of bounds (strict profile)");
    direct(() -> { A0Module.checked_then_trap(2); }, "A0710", "bounds", "checked_then_trap", BOUNDS_FIX,
        "checked_then_trap: index out of bounds (strict profile)");

    var empty = new A0Module.A0Io(new int[0]);
    direct(() -> { A0Module.input_after_write(empty); }, "A0712", "input", "input_after_write", INPUT_FIX,
        "input_after_write: read of exhausted input (strict profile)");
    FixtureAssertions.ok(empty.position == 0 && empty.noutput == 1 && empty.output[0] == 77,
        "write before exhausted read remains visible");
    var supplied = new A0Module.A0Io(new int[]{41});
    FixtureAssertions.ok(A0Module.input_after_write(supplied) == 41 && supplied.position == 1
        && supplied.noutput == 1 && supplied.output[0] == 77, "fresh IO succeeds after trap");
    direct(() -> { A0Module.input_after_write(empty); }, "A0712", "input", "input_after_write", INPUT_FIX,
        "input_after_write: read of exhausted input (strict profile)");
    FixtureAssertions.ok(empty.position == 0 && empty.noutput == 2 && empty.output[1] == 77,
        "repeated trap preserves both earlier writes");

    for (int repeat = 0; repeat < 2; repeat++) {
      FixtureAssertions.ok(A0Module.trap_outer(2) == 30, "successful framed call after prior trap");
      trap(() -> { A0Module.trap_outer(3); }, "A0710", "bounds", "trap_step", "trap_top.r", "2",
          new String[]{"trap_outer", "trap_top", "trap_step"}, BOUNDS_FIX,
          "trap_step: index out of bounds (strict profile)");
    }
    trap(() -> { A0Module.pred_top(2); }, "A0710", "bounds", "pred_bad", "pred_top.r", "1",
        new String[]{"pred_top", "pred_bad"}, BOUNDS_FIX,
        "pred_bad: index out of bounds (strict profile)");
